40|export interface SessionView {
41|  currentId: string | null;
42|  fadeSec: number;
43|  replayNonce: number;
44|  canPrev: boolean;
45|  canSkip: boolean;
46|  playlistOn: boolean;
47|  style: string | null;
48|}
49|
50|export interface SessionContext {
51|  manifest: MusicManifest;
52|  signalOf: (sceneId: string) => SceneSignal | null;
53|  routeSceneId: string | null;
54|  nowSec: number;
55|  rng: Rng;
56|}
57|
58|export type MusicIntent =
59|  | { type: "sceneEntered"; sceneId: string }
60|  | { type: "tick" }
61|  | { type: "skip" }
62|  | { type: "previous" }
63|  | { type: "styleChanged"; style: string }
64|  | { type: "trackEnded"; trackId: string }
65|  | { type: "playlistToggled" }
66|  | { type: "modeAdvanced"; to?: MusicModeId };
67|
68|// Route entries use the short dwell; the draw and the holds are unchanged.
69|const ENTRY_DWELL = { dwellSec: MUSIC_CONFIG.sceneEntryDwellSec };
70|
71|export function startSession(
72|  manifest: MusicManifest,
73|  prefs: PersistedMusicPrefs | null,
74|): MusicSession {
75|  const fields = {
76|    scheduler: initScheduler(),
77|    history: [] as string[],
78|    selection: resolveInitialSelection(manifest, prefs),
79|    fadeSec: 0,
80|    replayNonce: 0,
81|  };
82|  // A stored Chopin mode starts in the playlist at once (fade 0, like the
83|  // first scene entry); without the playlist the stored style stands.
84|  if (prefs?.playlist === true) {
85|    const playlist = findChopinPlaylist(manifest);
86|    if (playlist) {
87|      const decision = enterPlaylist(fields.scheduler, manifest, playlist.id, 0);
88|      const entered = foldSwitch(fields, decision, false);
89|      return { ...entered, view: buildView(entered, manifest, null, entered.selection) };
90|    }
91|  }
92|  return {
93|    ...fields,
94|    view: buildView(fields, manifest, null, fields.selection),
95|  };
96|}
